import * as React from "react"

function CardsOrder({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="cards-order"
      className={className}
      {...props}
    >
      <div className="flex flex-wrap gap-6 justify-center mt-8">

        <div className="border-4 border-[#00FF00] bg-white p-6 rounded-lg shadow-md w-64">
          <h3 className="font-bold text-xl mb-2 text-gray-800">Green Border</h3>
          <p className="text-gray-600">Subtle white background with bold green border.</p>
        </div>


        <div className="bg-gradient-to-br from-blue-500 to-[#0000FF] text-white p-6 rounded-lg shadow-lg w-64">
          <h3 className="font-bold text-xl mb-2">Blue Gradient</h3>
          <p className="opacity-90">Smooth fade to blue-100.</p>
        </div>


        <div className="bg-white border border-gray-300 p-6 rounded-lg shadow-sm w-64">
          <h3 className="font-bold text-xl mb-2 text-[#808080]">Gray Text</h3>
          <p className="text-gray-600">Uses gray-100 for headings.</p>
        </div>
      </div>
    </div>
  )
}

export { CardsOrder }
